with valid_stores as (select * from stores where sqft = 8481), summary as (select date_format(opened_date, 'yyyy-MM') as opened_month, min(sqft) as min_sqft, sum(case when region = 'North' then 1 else 0 end) as north_count from valid_stores group by date_format(opened_date, 'yyyy-MM')) select opened_month, min_sqft, north_count from summary order by north_count desc, opened_month;
